1	import { useEffect, useState } from 'react';
2	import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
3	import {
4	  bindChildWithCode,
5	  fetchParentChildReport,
6	  fetchParentChildrenOverview,
7	  unbindChild,
8	} from '@/shared/api/viewer/parentApi';
9	import { EmptyStateCard, ErrorStateCard, LoadingStateCard } from '@/shared/layout/AsyncState';
10	import { PageContainer } from '@/shared/layout/PageContainer';
11	import { SurfaceCard } from '@/shared/layout/SurfaceCard';
12	import { captureViewerError, captureViewerEvent } from '@/shared/platform/observability';
13	import { useProductLanguage } from '@/shared/i18n/useProductLanguage';
14	import { useViewerCopy } from '@/shared/theme/copy';
15	
16	export function ParentDashboardPage() {
17	  const language = useProductLanguage();
18	  const copy = useViewerCopy();
19	  const queryClient = useQueryClient();
20	  const [selectedChildId, setSelectedChildId] = useState<string>('');
21	  const [bindCodeInput, setBindCodeInput] = useState('');
22	  const [bindingStatus, setBindingStatus] = useState('');
23	
24	  const childrenQuery = useQuery({
25	    queryKey: ['viewer', 'parent-children'],
26	    queryFn: fetchParentChildrenOverview,
27	  });
28	
29	  useEffect(() => {
30	    if (!selectedChildId && childrenQuery.data?.[0]?.child_id) {
31	      setSelectedChildId(childrenQuery.data[0].child_id);
32	    }
33	  }, [childrenQuery.data, selectedChildId]);
34	
35	  const reportQuery = useQuery({
36	    queryKey: ['viewer', 'parent-report', selectedChildId],
37	    queryFn: () => fetchParentChildReport(selectedChildId),
38	    enabled: Boolean(selectedChildId),
39	  });
40	
41	  const bindChildMutation = useMutation({
42	    mutationFn: () => bindChildWithCode(bindCodeInput),
43	    onSuccess: async (payload) => {
44	      await queryClient.invalidateQueries({ queryKey: ['viewer', 'parent-children'] });
45	      setSelectedChildId('');
46	      setBindCodeInput('');
47	      setBindingStatus(
48	        payload.ok
49	          ? language === 'zh-CN'
50	            ? '已绑定孩子。'
51	            : 'Child bound.'
52	          : language === 'zh-CN'
53	            ? '绑定失败。'
54	            : 'Binding failed.',
55	      );
56	      captureViewerEvent('viewer_parent_bind_child', { ok: payload.ok });
57	    },
58	    onError: (error) => {
59	      setBindingStatus(error instanceof Error ? error.message : language === 'zh-CN' ? '绑定失败。' : 'Binding failed.');
60	      captureViewerError(error, { area: 'parent_bind_child' });
61	    },
62	  });
63	
64	  const unbindMutation = useMutation({
65	    mutationFn: () => unbindChild(selectedChildId),
66	    onSuccess: async (payload) => {
67	      await queryClient.invalidateQueries({ queryKey: ['viewer', 'parent-children'] });
68	      await queryClient.invalidateQueries({ queryKey: ['viewer', 'parent-report', selectedChildId] });
69	      setSelectedChildId('');
70	      setBindingStatus(
71	        payload.ok
72	          ? language === 'zh-CN'
73	            ? '已解除孩子绑定。'
74	            : 'Child unbound.'
75	          : language === 'zh-CN'
76	            ? '解除绑定失败。'
77	            : 'Unbind failed.',
78	      );
79	      captureViewerEvent('viewer_parent_unbind_child', { ok: payload.ok });
80	    },
81	    onError: (error) => {
82	      setBindingStatus(error instanceof Error ? error.message : language === 'zh-CN' ? '解除绑定失败。' : 'Unbind failed.');
83	      captureViewerError(error, { area: 'parent_unbind_child' });
84	    },
85	  });
86	
87	  const children = childrenQuery.data ?? [];
88	  const report = reportQuery.data;
89	
90	  if (childrenQuery.isLoading) {
91	    return (
92	      <PageContainer title={copy.parent.title} subtitle={copy.parent.subtitle}>
93	        <LoadingStateCard />
94	      </PageContainer>
95	    );
96	  }
97	
98	  if (childrenQuery.error) {
99	    return (
100	      <PageContainer title={copy.parent.title} subtitle={copy.parent.subtitle}>
101	        <ErrorStateCard
102	          message={childrenQuery.error instanceof Error ? childrenQuery.error.message : undefined}
103	          onRetry={() => void childrenQuery.refetch()}
104	        />
105	      </PageContainer>
106	    );
107	  }
108	
109	  return (
110	    <PageContainer title={copy.parent.title} subtitle={copy.parent.subtitle}>
111	      <SurfaceCard className="space-y-3">
112	        <h2 className="text-xl font-black text-[var(--viewer-text)]">{language === 'zh-CN' ? '绑定学习者' : 'Bind learner'}</h2>
113	        <div className="flex flex-col gap-3 sm:flex-row">
114	          <input
115	            className="min-w-0 flex-1 rounded-2xl border border-[var(--viewer-border)] px-4 py-3 outline-none"
116	            value={bindCodeInput}
117	            onChange={(event) => setBindCodeInput(event.target.value)}
118	            placeholder={language === 'zh-CN' ? '输入孩子绑定码' : 'Bind child with code'}
119	          />
120	          <button
121	            type="button"
122	            className="rounded-2xl bg-[var(--viewer-primary)] px-4 py-3 text-sm font-black text-white"
123	            onClick={() => bindChildMutation.mutate()}
124	            disabled={!bindCodeInput.trim() || bindChildMutation.isPending}
125	          >
126	            {bindChildMutation.isPending ? copy.parent.binding : copy.parent.bind}
127	          </button>
128	        </div>
129	      </SurfaceCard>
130	
131	      {bindingStatus ? (
132	        <SurfaceCard>
133	          <p className="text-sm font-semibold text-[var(--viewer-text-muted)]">{bindingStatus}</p>
134	        </SurfaceCard>
135	      ) : null}
136	
137	      <div className="grid gap-4 xl:grid-cols-[360px_minmax(0,1fr)]">
138	        <SurfaceCard className="space-y-3">
139	          {children.length === 0 ? <EmptyStateCard message={language === 'zh-CN' ? '还没有已绑定的学习者。' : 'No linked learners yet.'} /> : null}
140	          {children.map((child) => (
141	            <button
142	              key={child.child_id}
143	              type="button"
144	              className={
145	                selectedChildId === child.child_id
146	                  ? 'w-full rounded-3xl bg-indigo-50 px-4 py-4 text-left'
147	                  : 'w-full rounded-3xl border border-[var(--viewer-border)] px-4 py-4 text-left'
148	              }
149	              onClick={() => setSelectedChildId(child.child_id)}
150	            >
151	              <p className="text-sm font-black text-[var(--viewer-text)]">{child.child_name}</p>
152	              <p className="mt-2 text-sm font-medium text-[var(--viewer-text-muted)]">
153	                {language === 'zh-CN'
154	                  ? `${child.lessons_completed} 节课 · ${child.total_xp} XP`
155	                  : `${child.lessons_completed} lessons · ${child.total_xp} XP`}
156	              </p>
157	            </button>
158	          ))}
159	        </SurfaceCard>
160	
161	        <div className="grid gap-4">
162	          <SurfaceCard className="space-y-4">
163	            <div className="flex items-center justify-between">
164	              <h2 className="text-xl font-black text-[var(--viewer-text)]">{language === 'zh-CN' ? '当前孩子报告' : 'Selected child report'}</h2>
165	              <button
166	                type="button"
167	                className="rounded-2xl border border-rose-300 px-4 py-3 text-sm font-black text-rose-700"
168	                onClick={() => unbindMutation.mutate()}
169	                disabled={!selectedChildId || unbindMutation.isPending}
170	              >
171	                {unbindMutation.isPending ? copy.parent.unbinding : copy.parent.unbind}
172	              </button>
173	            </div>
174	            <div className="grid gap-3 md:grid-cols-2">
175	              <div className="rounded-2xl bg-[var(--viewer-surface-muted)] px-4 py-4">
176	                <p className="text-xs font-bold uppercase tracking-[0.18em] text-[var(--viewer-text-muted)]">{language === 'zh-CN' ? '总 XP' : 'Total XP'}</p>
177	                <p className="mt-2 text-lg font-black text-[var(--viewer-text)]">{report?.summary.total_xp ?? 0}</p>
178	              </div>
179	              <div className="rounded-2xl bg-[var(--viewer-surface-muted)] px-4 py-4">
180	                <p className="text-xs font-bold uppercase tracking-[0.18em] text-[var(--viewer-text-muted)]">{language === 'zh-CN' ? '连击' : 'Streak'}</p>
181	                <p className="mt-2 text-lg font-black text-[var(--viewer-text)]">{report?.summary.streak ?? 0}</p>
182	              </div>
183	              <div className="rounded-2xl bg-[var(--viewer-surface-muted)] px-4 py-4">
184	                <p className="text-xs font-bold uppercase tracking-[0.18em] text-[var(--viewer-text-muted)]">{language === 'zh-CN' ? '完成课时' : 'Lessons completed'}</p>
185	                <p className="mt-2 text-lg font-black text-[var(--viewer-text)]">{report?.summary.lessons_completed ?? 0}</p>
